import hmac, hashlib

SECRET = b"server-side-secret"

def sign(msg: bytes) -> str:
    return hmac.new(SECRET, msg, hashlib.sha256).hexdigest()

def verify_bad(msg: bytes, sig: str) -> bool:
    return sign(msg) == sig          # 普通比较：可能提前返回，耗时泄露前缀匹配长度

def verify_good(msg: bytes, sig: str) -> bool:
    # compare_digest 的耗时不取决于两者有多少前缀相同
    return hmac.compare_digest(sign(msg), sig)

# Node.js 等价写法：crypto.timingSafeEqual(bufA, bufB)（要求长度相同）
print(verify_good(b"order=42", sign(b"order=42")))   # True

-- PostgreSQL + Citus 扩展：按 tenant_id 把表分布到多个 worker 节点
CREATE EXTENSION IF NOT EXISTS citus;

CREATE TABLE orders (
  tenant_id  bigint NOT NULL,
  order_id   bigint NOT NULL,
  amount     numeric(12,2),
  created_at timestamptz DEFAULT now(),
  PRIMARY KEY (tenant_id, order_id)     -- 主键需包含分布列
);

SELECT create_distributed_table('orders', 'tenant_id');

-- 小而常被关联的维表复制到每个节点
CREATE TABLE countries (code text PRIMARY KEY, name text);
SELECT create_reference_table('countries');

-- 带分片键的查询只路由到一个分片
SELECT sum(amount) FROM orders WHERE tenant_id = 42;

-- 父表：按 created_at 做范围分区
CREATE TABLE events (
  id         bigint GENERATED ALWAYS AS IDENTITY,
  created_at timestamptz NOT NULL,
  payload    jsonb,
  PRIMARY KEY (id, created_at)          -- 主键必须包含分区键
) PARTITION BY RANGE (created_at);

-- 子分区：区间左闭右开
CREATE TABLE events_2026_10 PARTITION OF events
  FOR VALUES FROM ('2026-10-01') TO ('2026-11-01');
CREATE TABLE events_2026_11 PARTITION OF events
  FOR VALUES FROM ('2026-11-01') TO ('2026-12-01');

-- 查询带分区键，EXPLAIN 可看到只扫描一个分区
EXPLAIN SELECT count(*) FROM events
WHERE created_at >= '2026-10-15' AND created_at < '2026-10-16';

-- 归档旧数据：分离后删除，代替大规模 DELETE
ALTER TABLE events DETACH PARTITION events_2026_10;
DROP TABLE events_2026_10;

-- 1) 哪些表死元组最多、上次 autovacuum 是什么时候
SELECT relname, n_live_tup, n_dead_tup, last_autovacuum
FROM pg_stat_user_tables
ORDER BY n_dead_tup DESC LIMIT 10;

-- 2) 是否有长事务阻止清理（xact_start 很早的会话）
SELECT pid, state, xact_start, left(query, 60)
FROM pg_stat_activity
WHERE xact_start IS NOT NULL ORDER BY xact_start LIMIT 5;

-- 3) 各数据库距离回卷还有多远（年龄越大越危险）
SELECT datname, age(datfrozenxid) FROM pg_database ORDER BY 2 DESC;

-- 4) 大表单独调低触发比例，让 autovacuum 更早更频繁运行
ALTER TABLE orders SET (autovacuum_vacuum_scale_factor = 0.02);

-- 5) 手动执行（不锁表读写），并更新统计信息
VACUUM (VERBOSE, ANALYZE) orders;

-- 业务事务：订单与事件一起提交，要么都成功，要么都回滚
BEGIN;
INSERT INTO orders (id, user_id, amount) VALUES (1001, 7, 99.00);
INSERT INTO outbox (id, aggregate_type, aggregate_id, event_type, payload)
VALUES (gen_random_uuid(), 'order', '1001', 'OrderCreated',
        '{"orderId":1001,"amount":99.00}');
COMMIT;

-- 中继进程：批量取未发送事件，多实例并发时互不抢同一行
BEGIN;
SELECT id, event_type, payload FROM outbox
WHERE sent_at IS NULL
ORDER BY created_at
LIMIT 100
FOR UPDATE SKIP LOCKED;
-- ……逐条发送到消息队列，成功后：
UPDATE outbox SET sent_at = now() WHERE id = ANY($1);
COMMIT;
